using FlexCore.Showcase.Components.Shared;

namespace FlexCore.Showcase.Components.Pages.Demos.Charts;

public static partial class ChartsVocab
{
    public static readonly ApiRow[] Params =
    {
        // Data
        new("Type", "Selects the SVG renderer. <code>HorizontalBar</code>, <code>GroupedBar</code>, <code>StackedBar</code>, <code>StackedBar100</code>, <code>Pareto</code>, <code>ComboBarLine</code> and <code>Treemap</code> (which has no case of its own) all go to the bar renderer, and <code>HorizontalBar</code> still draws vertical bars. Not consulted in legacy mode: with <code>Series</code> null and <code>Bars</code> or <code>DataSource</code> set, the control renders HTML bars whatever <code>Type</code> says.", "ChartType", "ChartType.Bar"),
        new("Series", "Data for every SVG type. A non-null value, even an empty list, puts the control in SVG mode and makes it ignore <code>Bars</code> and <code>DataSource</code>; null with neither of those set is SVG mode too, and only <code>KpiCard</code> and the gauge types render without data (everything else shows <em>No data</em>). Most single-series types read only <code>Series[0]</code>; <code>ComboBarLine</code> draws <code>Series[1]</code> as its line and <code>Heatmap</code> uses one series per row.", "List&lt;ChartSeries&gt;?", "null"),
        new("DataSource", "Legacy multi-row mode: when <code>Series</code> is null and <code>Bars</code> is null or empty, each item becomes one HTML row of grouped vertical bars. Needs <code>ValueFields</code> with at least one name, otherwise nothing is resolved and the tile shows <em>No data</em>. Values are read by reflection on each item's runtime type.", "System.Collections.IEnumerable?", "null"),
        new("LabelField", "Legacy multi-row mode only: property name whose <code>ToString()</code> becomes the row label; null or a missing property gives an empty label.", "string?", "null"),
        new("ValueFields", "Legacy multi-row mode only: property names read from each <code>DataSource</code> item, in order, one bar per name. Each value goes through <code>Convert.ToDouble</code>; a missing property, null or unconvertible value becomes 0. Bars are scaled against the largest value across all rows.", "IList&lt;string&gt;?", "null"),
        new("ValueLabels", "Legacy multi-row mode only: per-column captions used in each bar's hover tooltip and, while <code>ShowAxisLabels</code> is true, as the bottom axis ticks (the axis is skipped entirely when this is null or empty). Columns beyond the list get an empty tooltip caption.", "IList&lt;string&gt;?", "null"),
        new("Bars", "Legacy single-series mode: when <code>Series</code> is null and this has at least one entry, each <code>ChartBar</code> becomes one HTML row with a horizontal bar sized as a percentage of the largest value (clamped 0 to 100; a non-positive maximum counts as 1). A non-empty <code>Bars</code> wins over <code>DataSource</code>; an empty list falls through to it. <code>ChartBar.Color</code> overrides <code>BarColor</code> per row.", "IList&lt;ChartBar&gt;?", "null"),
        new("RowType", "Declared, but <code>ChartControl</code> never reads it. Legacy mode reflects on each item's runtime type instead.", "Type?", "null"),
        // Appearance
        new("Title", "Rendered as a <code>fx-chart-title</code> div above the chart in both modes when not empty. <code>Sunburst</code> also uses it as the name of the root node (<em>Total</em> when empty).", "string?", "null"),
        new("Width", "Written as <code>width</code> on the root <code>fx-chart</code> div when not empty; the scoped CSS otherwise makes the root 100% wide. The <code>svg</code> inside is always 100% of that width.", "string?", "null"),
        new("Height", "CSS <code>height</code> of the <code>svg</code> only: every SVG type draws on a fixed viewBox (600×300 for most types; 300×300 for Pie, Donut, Radar and the round gauges; 400×300 Funnel; 200×40 Sparkline) scaled with <code>xMidYMid meet</code>, so a narrow tile shows the drawing centred between blank bands. Not read in legacy HTML bar mode or by <code>KpiCard</code>, and <code>Sunburst</code> hands it to <code>SunburstChartControl</code>, which never reads it. An explicit null selects a per-type fallback (40px Sparkline, 260px gauges, 320px financial, 340px Sankey, 60px per point for Bullet, else 300px).", "string?", "\"300px\""),
        new("CssClass", "Appended to the root <code>fx-chart</code> div's class list in both modes.", "string?", "null"),
        new("ColorPalette", "Replaces the eight built-in colours that <code>GetSeriesColor</code> and <code>GetPointColor</code> cycle through; <code>ChartSeries.Color</code> and <code>ChartDataPoint.Color</code> still win, and entry 0 also colours the gauge arc. The types with colours of their own read single entries, without cycling, and keep their own colour where the palette has no such entry: entry 0 is the bar of <code>RangeBar</code>, <code>RangeColumn</code> and <code>RangeArea</code>, the line of <code>HighLow</code>, the actual bar of <code>Bullet</code>, the source nodes and ribbons of <code>Sankey</code>, and the top of the <code>Heatmap</code> ramp when it is a hex colour; entry 1 is the <code>Pareto</code> line, the <code>Bullet</code> target line and the <code>Sankey</code> target nodes. <code>Waterfall</code>, <code>Candlestick</code> and <code>Ohlc</code> colour by direction instead (<code>UpColor</code>, <code>DownColor</code>). Not read in legacy mode (see <code>BarColor</code>).", "string[]?", "null"),
        new("UpColor", "Rising candles and <code>Ohlc</code> bars (close at or above open) and positive <code>Waterfall</code> steps. Unset, a candle has a <code>#22c55e</code> body with a <code>#16a34a</code> wick and outline, and the other two use <code>#16a34a</code>; set, the body, wick and outline all take it. A Waterfall point's <code>Color</code> still wins.", "string?", "null"),
        new("DownColor", "Falling candles and <code>Ohlc</code> bars and negative <code>Waterfall</code> steps. Unset, a candle has a <code>#ef4444</code> body with a <code>#dc2626</code> wick and outline, and the other two use <code>#dc2626</code>; set, all of them take it. A Waterfall point's <code>Color</code> still wins.", "string?", "null"),
        new("Animate", "Declared, but <code>ChartControl</code> never reads it; no renderer emits an animation and the only transitions are the fixed CSS ones on the legacy bars. <code>ChartSvg.Markup</code> passes it as false.", "bool", "false"),
        new("InnerRadius", "<code>Donut</code> only: inner radius as a fraction of the outer one, 0.6 when null; the value is not clamped. <code>Pie</code> always uses 0 and no other type reads it.", "double?", "null"),
        new("LabelStyle", "Legacy HTML bar mode only: inline style on the row label cell of both the <code>Bars</code> and the <code>DataSource</code> layouts, applied only while <code>ShowLabels</code> is true. The multi-row bottom axis keeps its own fixed 160px spacer in CSS, so a different width here misaligns the axis ticks. Never read by the SVG types.", "string?", "\"min-width:160px;\""),
        new("BarColor", "Legacy HTML bar mode only: fill of every bar, with <code>ChartBar.Color</code> overriding it per row in <code>Bars</code> mode (the multi-row layout has no per-bar override); null falls back to the same blue. Never read by the SVG types, which use <code>ColorPalette</code>.", "string?", "\"#2563eb\""),
        // Axes and legend
        new("XAxis", "Only <code>XAxis.Title</code> is read, drawn under the plot by the bar family and the line/area family. <code>Min</code>, <code>Max</code>, <code>Format</code>, <code>ShowGridLines</code> and <code>TickCount</code> of the X axis are never read; no type offers an X scale override.", "ChartAxis?", "null"),
        new("YAxis", "<code>Min</code>/<code>Max</code> replace the padded data range in the bar family, the line/area family, <code>Waterfall</code>, <code>BoxPlot</code> and <code>Histogram</code> (a maximum not above the minimum is pushed to minimum + 1); <code>TickCount</code> (5 when unset, the number of labelled grid lines) is honoured by the bar and line/area families only; <code>Title</code> is drawn rotated at the left edge by those same two families. <code>Format</code> and <code>ShowGridLines</code> are never read: tick labels always use <code>F0</code> and the dashed grid is always drawn.", "ChartAxis?", "null"),
        new("Legend", "<code>Legend.Visible</code> (true when the object is null) gates the shared legend that SVG mode appends below the drawing when <code>Series</code> has more than one entry; swatches come from <code>GetSeriesColor</code>. <code>Pie</code> and <code>Donut</code> add their own per-slice legend regardless of this setting. <code>Legend.Position</code> is never read; the legend always sits under the chart.", "ChartLegend?", "null"),
        // Legacy flags
        new("ShowLabels", "Legacy HTML bar mode only: renders the label cell (styled by <code>LabelStyle</code>) at the start of each <code>Bars</code> row or <code>DataSource</code> row. Never read by the SVG types, which always draw their own category labels.", "bool", "true"),
        new("ShowValues", "Legacy HTML bar mode only: writes each value, formatted with <code>ValueFormat</code>, beside a <code>Bars</code> bar or above a <code>DataSource</code> bar. Never read by the SVG types, whose values live in hover <code>&lt;title&gt;</code> tooltips.", "bool", "false"),
        new("ShowAxisLabels", "Legacy <code>DataSource</code> mode only: renders the bottom axis row of <code>ValueLabels</code> captions, and only when that list has entries. Not read in <code>Bars</code> mode or by any SVG type.", "bool", "true"),
        new("ValueFormat", "Format string for the legacy value captions shown by <code>ShowValues</code> (the hover tooltips there always use <code>N2</code>), and for the value text of <code>Gauge</code>, <code>ArcGauge</code>, <code>RadialGauge</code> and <code>LinearGauge</code> through <code>GaugeVisualControl</code>, where this default overrides that control's own <code>0.##</code>, so a gauge shows two decimals unless you set it. Not read by any other SVG type.", "string", "\"N2\""),
        // Tooltips (2026-10-31): one card per hovered shape, Blazor events only, no script.
        new("ShowTooltips", "Shows a card when the pointer is over a bar, slice, point, cell, flow or marker, with the label, the series and the value, and the share of the whole for <code>Pie</code>, <code>Donut</code>, <code>Funnel</code> and <code>Pyramid</code>. Off, the shapes keep their native <code>&lt;title&gt;</code> text. Gauges, KPI cards and sparklines have no card.", "bool", "true"),
        new("TooltipValueFormat", ".NET numeric format for the numbers in the default card. Unset, whole numbers print as <code>N0</code> and the rest as <code>N2</code>.", "string?", "null"),
        new("TooltipFormat", "Text pattern that replaces the card's rows: <code>{series}</code> <code>{label}</code> <code>{category}</code> <code>{title}</code> <code>{value}</code> <code>{value2}</code>…<code>{value5}</code> <code>{percent}</code> <code>{open}</code> <code>{high}</code> <code>{low}</code> <code>{close}</code> <code>{min}</code> <code>{max}</code> <code>{size}</code>; a format after a colon applies to numbers (<code>{value:N0}</code>); <code>\n</code> starts a new row.", "string?", "null"),
        new("TooltipFormatter", "Code-side text for the card's rows, lines separated by <code>\n</code>; return null to fall back to <code>TooltipFormat</code> or the default rows.", "Func&lt;ChartTooltipContext, string?&gt;?", "null"),
        new("TooltipTemplate", "Replaces the whole card content; the context is the hovered shape.", "RenderFragment&lt;ChartTooltipContext&gt;?", "null"),
        new("PointHover", "Raised with the context when the pointer enters a shape and with null when it leaves the shape or the chart.", "EventCallback&lt;ChartTooltipContext?&gt;"),
        // 30 rows
    };

